SELECT t.*, m.material_name, fl.location_name as from_location_name, tl.location_name as to_location_name FROM mes_inventory_transaction t LEFT JOIN mes_material m ON t.material_id = m.id LEFT JOIN mes_warehouse_location fl ON t.from_location_id = fl.id LEFT JOIN mes_warehouse_location tl ON t.to_location_id = tl.id WHERE 1=1
AND t.material_code LIKE CONCAT('%', #{vo.materialCode}, '%')
AND t.transaction_type = #{vo.transactionType}
AND t.reference_type = #{vo.referenceType}
AND t.reference_code LIKE CONCAT('%', #{vo.referenceCode}, '%')
AND t.transaction_time >= #{vo.startTime}
AND t.transaction_time <= #{vo.endTime}
ORDER BY t.transaction_time DESC

SELECT *
FROM mes_inventory_transaction
WHERE reference_type = #{referenceType}
  AND reference_id = #{referenceId}
ORDER BY transaction_time DESC
